CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.trial_balance
COMMENT 'The trial balance: net movement by ledger account, entity and period, from the journal lines. Because every journal balances, the total across all accounts nets to zero - the controller''s first check. Query with MEASURE(net_movement); always constrain currency_code.'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_finance.journal_line

joins:
  - name: account
    source: lr_serverless_aws_us_catalog.bricksurance_finance.chart_of_account
    on: source.account_id = account.account_id
  - name: journal
    source: lr_serverless_aws_us_catalog.bricksurance_finance.journal
    on: source.journal_id = journal.journal_id

dimensions:
  - name: account_number
    expr: account.account_number
  - name: account_name
    expr: account.name
  - name: account_type
    expr: account.account_type_code
  - name: statement_type
    expr: account.statement_type_code
  - name: legal_entity_id
    expr: journal.legal_entity_id
  - name: currency_code
    expr: source.currency_code

measures:
  - name: net_movement
    expr: SUM(amount)
  - name: total_debits
    expr: SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END)
  - name: total_credits
    expr: SUM(CASE WHEN amount < 0 THEN -amount ELSE 0 END)
$$;
